async def index_all_subjects(
    subject_type: Literal['subject', 'person', 'place', 'time'],
    chunk_size=10_000,
    instances=2,
    solr_base_url='http://solr:8983/solr/openlibrary',
    skip_id_check=False,
):
    done = False
    active_workers: set[Future] = set()
    offset = 0
    while True:
        if done:
            # Done! Wait for any previous workers that are still going
            await asyncio.gather(*active_workers)
            break
        elif len(active_workers) >= instances:
            # Too many running; wait for one to finish
            finished, pending = await asyncio.wait(
                active_workers, return_when=asyncio.FIRST_COMPLETED

        // Save Progress Files
        sh '''tail --quiet -n1 $(ls -tr progress/orphans/*) | gzip > progress/orphans-progress.txt.gz'''
        archiveArtifacts artifacts: "progress/orphans-progress.txt.gz"
        // Save Log Files
        sh '''cat $(ls -tr logs/orphans/*) | gzip > logs/orphans-indexing.log.gz'''
        archiveArtifacts artifacts: "logs/orphans-indexing.log.gz"
      }
    }
  }
